import assert from 'node:assert/strict';
import isCreditCard from './lib/isCreditCard.js';

// Controls: genuine 16-digit Luhn-valid Mastercards must pass.
assert.equal(isCreditCard('5105105105105100', { provider: 'mastercard' }), true);
assert.equal(isCreditCard('2221000000000009', { provider: 'mastercard' }), true);

// Prefix branch bug: ^5[1-5][0-9]{2} has no $ anchor.
// '510008' is Luhn-valid (sum 10) and starts 5100, but is only 6 digits.
assert.equal(isCreditCard('510008', { provider: 'mastercard' }), false);
// '51051051051051005' is Luhn-valid (sum 30) and starts 5105, but is 17 digits.
assert.equal(isCreditCard('51051051051051005', { provider: 'mastercard' }), false);

// Suffix branch bug: second alternative has no ^ anchor.
// '92221000000000000' is Luhn-valid (sum 20), 17 digits starting with 9,
// but ends with 2221 + 12 digits, so the unanchored branch matches.
assert.equal(isCreditCard('92221000000000000', { provider: 'mastercard' }), false);

import assert from 'node:assert/strict';
import { isISO6346 } from './lib/isISO6346.js';

// Valid IDs should be accepted.
assert.equal(isISO6346('CSQU3054383'), true);
assert.equal(isISO6346('ABCU1234560'), true);
assert.equal(isISO6346('ABCJ123456'), true);

// Extra suffix: first alternation branch lacks a trailing anchor.
assert.equal(isISO6346('ABCU1234560XYZ'), false);
assert.equal(isISO6346('ABCU1234567XYZ'), false);

// Extra prefix: second alternation branch lacks a leading anchor.
assert.equal(isISO6346('GARBAGEJ123456'), false);
assert.equal(isISO6346('XXXXZ1234567'), false);

// Comma: [J,Z] incorrectly includes a literal comma as category.
assert.equal(isISO6346('ABC,123456'), false);
assert.equal(isISO6346(',123456'), false);

import assert from 'node:assert/strict';
import isLicensePlate from './lib/isLicensePlate.js';

// Valid pt-BR plates must pass
assert.equal(isLicensePlate('ABC1234', 'pt-BR'), true);
assert.equal(isLicensePlate('ABC-1234', 'pt-BR'), true);
assert.equal(isLicensePlate('ABC1D23', 'pt-BR'), true);
assert.equal(isLicensePlate('ABC-1D23', 'pt-BR'), true);

// Extra suffix after Mercosur format must be rejected (first branch lacks $)
assert.equal(isLicensePlate('ABC1D23X', 'pt-BR'), false);
assert.equal(isLicensePlate('ABC1D234', 'pt-BR'), false);
assert.equal(isLicensePlate('ABC1D23XYZ', 'pt-BR'), false);

// Extra prefix before old format must be rejected (second branch lacks ^)
assert.equal(isLicensePlate('XABC1234', 'pt-BR'), false);
assert.equal(isLicensePlate('XYZABC1234', 'pt-BR'), false);
assert.equal(isLicensePlate('1ABC1234', 'pt-BR'), false);
assert.equal(isLicensePlate(' ABC1234', 'pt-BR'), false);

import assert from 'node:assert/strict';
import isCurrency from './lib/isCurrency.js';

function check(str, options) {
  let result;
  let error = null;
  try {
    result = isCurrency(str, options);
  } catch (e) {
    error = e;
  }
  return { result, error };
}

let validDoubleDollar = check('$$10.00', { symbol: '$$', require_symbol: true });
assert.equal(validDoubleDollar.error, null);
assert.equal(validDoubleDollar.result, true);

let wildcardBypass = check('.a10.00', { symbol: '..', require_symbol: true });
assert.equal(wildcardBypass.error, null);
assert.equal(wildcardBypass.result, false);

let validPlus = check('$+10.00', { symbol: '$+', require_symbol: true });
assert.equal(validPlus.error, null);
assert.equal(validPlus.result, true);

let missingPlus = check('$10.00', { symbol: '$+', require_symbol: true });
assert.equal(missingPlus.error, null);
assert.equal(missingPlus.result, false);

import assert from 'node:assert/strict';
import isVAT from './lib/isVAT.js';

assert.equal(isVAT('', 'HN'), false, 'empty string must not be a valid HN VAT');
assert.equal(isVAT('', 'PA'), false, 'empty string must not be a valid PA VAT');
